if (!function_exists('time_elapsed_string')) {

    /**
     * time_elapsed_string function
     *
     * @param	string	$datetime	Date String to convert to elapsed string
     * 
     */
    function time_elapsed_string($datetime, $full = false)
    {
        $now = new DateTime;
        $ago = new DateTime($datetime);
        $diff = $now->diff($ago);

        $diff->w = floor($diff->d / 7);
        $diff->d -= $diff->w * 7;

        $string = array(
            'y' => 'year',
            'm' => 'month',
            'w' => 'week',
            'd' => 'day',
            'h' => 'hour',
            'i' => 'minute',
            's' => 'second',
        );
        foreach ($string as $k => &$v) {
            if ($diff->$k) {
                $v = $diff->$k . ' ' . $v . ($diff->$k > 1 ? 's' : '');
            } else {
                unset($string[$k]);
            }
        }

        if (!$full)
            $string = array_slice($string, 0, 1);
        return $string ? implode(', ', $string) . ' ago' : 'just now';
    }
}


if (!function_exists('time_left')) {

    /**
     * time_left function
     *
     * @param	string	$datetime	Date String to convert to remaining time left
     * 
     */
    function time_left($added_datetime, $expire_datetime)
    {
        $now = time();
        $added = strtotime($added_datetime);
        $expire = strtotime($expire_datetime);
        if ($now >= $expire) {
            return 1;
        }
        $max_time = $expire - $added;
        $passed = $now - $added;

        $time_left = (($max_time - $passed) / $max_time);
        // $time_left = 2;

        return round((1 - $time_left), 2);
    }
}

