    //     $return_hrs_left = round($hrs_left);
    //     if ($return_hrs_left <= 0) {
    //         $return_hrs_left = 0;
    //     }
    //     $return_hrs_left = 10;
    //     return $return_hrs_left;
    // }

    function hours_left($added_datetime, $expire_datetime)
    {
        $ci = &get_instance();
        $user_timezone = $ci->session->userdata("user_timezone");

        if (empty($user_timezone)) {
            $user_timezone = 'UTC';
        }

        $utc_now = new DateTime('now', new DateTimeZone('UTC'));
        $kolkata_now = new DateTime('now', new DateTimeZone($user_timezone));
        $expire_utc = new DateTime($expire_datetime, new DateTimeZone('UTC'));

        $offset = $kolkata_now->getOffset() - $utc_now->getOffset();
        $interval = gmdate('H:i:s', abs($offset));

        $hours = floor($offset / 3600);

        $expire_user_tz = clone $expire_utc;
        $expire_user_tz->setTimezone(new DateTimeZone($user_timezone));

        $now_user_tz = clone $utc_now;
        $now_user_tz->setTimezone(new DateTimeZone($user_timezone));

        $interval = $utc_now->diff($expire_utc);
        $hours_left = ($interval->days * 24) + $interval->h + ($interval->i / 60) - $hours;

        $return_hrs_left = round($hours_left);
        if ($return_hrs_left <= 0) {
            $return_hrs_left = 0;
        }

        return $return_hrs_left;
    }

